//! Decode PNG files produced by a *different* implementation.
//!
//! The round-trip tests inside the crate only prove the encoder and decoder
//! agree with each other — they would both pass if, say, the Paeth predictor
//! were wrong in a self-consistent way. These fixtures were generated by
//! CPython's `zlib` (level 9, so genuine dynamic-Huffman blocks with
//! back-references) with the scanline filters cycled through all five types,
//! and the expected pixels were computed independently of this crate.

use cv_core::MatLike;
use cv_imgcodecs::{imdecode, ImreadMode};

/// 24x18 RGB, filters cycling 0,1,2,3,4 across rows, zlib level 9.
const REF_RGB: &[u8] = include_bytes!("data/ref_rgb.png");
/// The same image's expected pixels, in Mat (BGR) order.
const REF_RGB_BGR: &[u8] = include_bytes!("data/ref_rgb.bgr");
/// 6x4 16-bit greyscale, filters cycling 4,2,3,1.
const REF_G16: &[u8] = include_bytes!("data/ref_g16.png");

#[test]
fn decodes_a_foreign_rgb_png_exactly() {
    let m = imdecode(REF_RGB, ImreadMode::Unchanged).unwrap();
    assert_eq!(m.size(), cv_core::Size::new(24, 18));
    assert_eq!(m.channels(), 3);
    assert_eq!(m.to_vec::<u8>().unwrap(), REF_RGB_BGR);
}

#[test]
fn decodes_a_foreign_16bit_grayscale_png_exactly() {
    let m = imdecode(REF_G16, ImreadMode::Unchanged).unwrap();
    assert_eq!(m.size(), cv_core::Size::new(6, 4));
    assert_eq!(m.depth(), cv_core::Depth::U16);

    // Expected values from the generator, recomputed here rather than stored.
    let expected: Vec<u16> = (0..4u32)
        .flat_map(|y| (0..6u32).map(move |x| ((x * 9000 + y * 1234) % 65536) as u16))
        .collect();
    assert_eq!(m.to_vec::<u16>().unwrap(), expected);
}

#[test]
fn foreign_png_survives_a_reencode_through_this_crate() {
    // Decode someone else's PNG, re-encode with ours, decode again: the pixels
    // must be identical, which exercises both directions against one another.
    let original = imdecode(REF_RGB, ImreadMode::Unchanged).unwrap();
    let ours = cv_imgcodecs::imencode(".png", &original).unwrap();
    let back = imdecode(&ours, ImreadMode::Unchanged).unwrap();
    assert_eq!(back.to_vec::<u8>().unwrap(), original.to_vec::<u8>().unwrap());
}

#[test]
fn mode_conversions_apply_to_foreign_pngs() {
    assert_eq!(imdecode(REF_RGB, ImreadMode::Grayscale).unwrap().channels(), 1);
    assert_eq!(imdecode(REF_RGB, ImreadMode::Color).unwrap().channels(), 3);
}
